"use client";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import * as React from "react";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Button, type ButtonProps } from "@/components/ui/button";
const ScrollerContext = React.createContext<{
  detached: boolean;
  jump: () => void;
} | null>(null);
export const messageScrollerVariants = cva(
  "v-scroller relative grid content-start auto-rows-min min-w-0 gap-[var(--s-3)] max-h-[var(--h,360px)] overflow-y-auto overflow-x-hidden p-[var(--s-4)] bg-[var(--card)] rounded-[var(--r-card)] overscroll-contain",
);
export type MessageScrollerProps = React.ComponentProps<"div"> & {
  followThreshold?: number;
  onAtBottomChange?: (atBottom: boolean) => void;
};
export function MessageScroller({
  ref,
  className,
  children,
  followThreshold = 24,
  onAtBottomChange,
  onScroll,
  ...props
}: MessageScrollerProps) {
  const element = React.useRef<HTMLDivElement>(null);
  const attached = React.useRef(true);
  const [detached, setDetached] = React.useState(false);
  const callback = React.useRef(onAtBottomChange);
  React.useEffect(() => {
    callback.current = onAtBottomChange;
  }, [onAtBottomChange]);
  const mark = React.useCallback(() => {
    const el = element.current;
    if (!el) return;
    const bottom =
      el.scrollHeight - el.scrollTop - el.clientHeight < followThreshold;
    if (attached.current !== bottom) {
      attached.current = bottom;
      setDetached(!bottom);
      callback.current?.(bottom);
    }
  }, [followThreshold]);
  const jump = React.useCallback(() => {
    const el = element.current;
    if (el) {
      el.scrollTop = el.scrollHeight;
      mark();
    }
  }, [mark]);
  React.useLayoutEffect(() => {
    const el = element.current;
    if (!el) return;
    jump();
    const follow = () => {
      if (attached.current) jump();
    };
    const resize = new ResizeObserver(follow);
    const observe = () => {
      resize.disconnect();
      resize.observe(el);
      for (const child of el.children) resize.observe(child);
      follow();
    };
    const mutation = new MutationObserver(observe);
    mutation.observe(el, {
      childList: true,
      subtree: true,
      characterData: true,
    });
    observe();
    return () => {
      mutation.disconnect();
      resize.disconnect();
    };
  }, [jump]);
  const ownedMorphRef = useMorph<HTMLDivElement>("surfaces", (node) => {
          element.current = node;
          if (typeof ref === "function") return ref(node);
          if (ref) ref.current = node;
        });
  return (
    <ScrollerContext.Provider value={{ detached, jump }}>
      <div
        ref={ownedMorphRef}
        data-slot="message-scroller"
        data-part="viewport"
        data-scroller=""
        data-state={detached ? "detached" : "attached"}
        className={cn(
          messageScrollerVariants(),
          detached && "-detached",
          className,
        )}
        onScroll={(event) => {
          mark();
          onScroll?.(event);
        }}
        {...props}
      >
        {children}
      </div>
    </ScrollerContext.Provider>
  );
}
export type MessageScrollerJumpProps = ButtonProps;
export function MessageScrollerJump({
  className,
  children,
  onClick,
  ...props
}: MessageScrollerJumpProps) {
  const scroller = React.useContext(ScrollerContext);
  return (
    <Button
      data-slot="message-scroller-jump"
      data-part="trigger"
      className={cn(
        "v-scroller__jump sticky bottom-0 justify-self-center",
        className,
      )}
      variant="secondary"
      size="sm"
      hidden={!scroller?.detached}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) scroller?.jump();
      }}
      {...props}
    >
      {children ?? "Jump to latest"}
    </Button>
  );
}

@layer sahajiv-states {
[data-slot="message-scroller"] {
  scroll-behavior: smooth;
  scrollbar-gutter: stable;
}
[data-slot="message-scroller"] > * {
  min-height: 0;
  overflow: visible;
}
[data-slot="message-scroller"] .v-card {
  height: auto;
}
[data-slot="message-scroller"] .v-bubble {
  border-radius: 18px 18px 18px 4px;
  box-shadow: inset 0 0 0 1px var(--v-border);
}
[data-slot="message-scroller-jump"][hidden] {
  display: none;
}
[data-slot="message-scroller"]::-webkit-scrollbar {
  width: 8px;
}
[data-slot="message-scroller"]::-webkit-scrollbar-track {
  background: transparent;
}
[data-slot="message-scroller"]::-webkit-scrollbar-thumb {
  background: color-mix(in oklab, var(--v-edge) 55%, transparent);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: content-box;
}
[data-slot="message-scroller"] .v-bubble,
[data-slot="message-scroller"] > div > * {
  transition: transform var(--t-element) var(--enter);
}

}
